measures.expression:
EXCEPT(
    CALCULATETABLE(
        SUMMARIZE('tbl_sales', 'tbl_sales'[F_在庫品目番号]),
        REMOVEFILTERS('tbl_sales')
    ),
    CALCULATETABLE(
        SUMMARIZE('tbl_item_bridge', 'tbl_item_bridge'[F_在庫品目番号]),
        REMOVEFILTERS('tbl_item_bridge')
    )
)

VAR Items = VALUES( tbl_sales_estimate[F_在庫品目番号] )
RETURN
CALCULATE (
    [直近材料費(円貨)],                                 // 既存の換算メジャー
    TREATAS ( Items, tbl_sales[F_在庫品目番号] ),        // 品目のフィルタを Sales へ注入
    USERELATIONSHIP(                                    // （必要なら）スナップショット↔Sales を有効化
        tbl_material_cost_snapshot[F_Sales_ID],
        tbl_sales[F_Sales_ID]
    )
    // リレーションが片方向で詰まる場合は、代わりに↓
    // CROSSFILTER( tbl_material_cost_snapshot[F_Sales_ID], tbl_sales[F_Sales_ID], BOTH )
)
